# Xen and Co - Sprint 1 (Bloco A)
# Estrutura: Header, Footer, Layout, Homepage, paginas /sobre /visitar /contacto

$ErrorActionPreference = "Stop"

if (-not (Test-Path "package.json")) {
    Write-Host "ERRO: corre dentro de xenco-surfshop" -ForegroundColor Red
    exit 1
}

Write-Host ""
Write-Host "Xen and Co - Sprint 1 Bloco A" -ForegroundColor Cyan
Write-Host "==============================" -ForegroundColor Cyan
Write-Host ""

# Criar pastas
$pastas = @(
    "src/app/(public)",
    "src/app/(public)/sobre",
    "src/app/(public)/visitar",
    "src/app/(public)/contacto",
    "src/components/ui",
    "src/components/layout",
    "src/data"
)

foreach ($p in $pastas) {
    [System.IO.Directory]::CreateDirectory("$PWD\$p") | Out-Null
}
Write-Host "OK Pastas criadas" -ForegroundColor Green

# Apagar page.tsx antiga em src/app/ (movemos para (public)/page.tsx)
if (Test-Path "src/app/page.tsx") {
    Remove-Item "src/app/page.tsx" -Force
    Write-Host "OK Apagado src/app/page.tsx (sera recriado em (public))" -ForegroundColor Yellow
}

Write-Host "A criar ficheiros..." -ForegroundColor Cyan

# src/data/site-config.ts
$b64 = ""
$path = "$PWD\src\data\site-config.ts"
$bytes = [System.Convert]::FromBase64String($b64)
$utf8 = [System.Text.UTF8Encoding]::new($false)
$text = $utf8.GetString($bytes)
[System.IO.File]::WriteAllText($path, $text, $utf8)
Write-Host "  OK src/data/site-config.ts" -ForegroundColor Gray

